import {ToolRegistry} from './registry.js';

describe('ToolRegistry', () => {
  it('rejects execute input missing a required property without calling executor ([validated by registry.acceptance.test.ts#L17])', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'get_weather',
        description: 'Get weather for a location',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      async () => {
        executorCalls += 1;
        return 'sunny';
      }
    );

    const response = await registry.execute('get_weather', {});

    expect(executorCalls).toBe(0);
    expect(response.result).toMatch(/location/);
    expect(response.result).toMatch(/required/i);
  });
});
